<?php
declare(strict_types=1);
require_once dirname(__DIR__,2).'/app/helpers/industry-classes.php';
$user=require_role('admin','staf_bkk');industry_require_ready();
$id=positive_id($_GET['id']??'');if(isset($_GET['id'])&&!$id){panel_not_found();}
$old=null;if($id){try{$old=industry_find($id);}catch(InvalidArgumentException){panel_not_found();}}
$data=$old?industry_input(array_map(static fn($value)=>(string)($value??''),$old)):industry_input(['rencana_pertemuan'=>'1','status'=>'aktif']);
$selectedSpeakers=$id?industry_refs($id,'speakers'):[];$selectedParticipants=$id?industry_refs($id,'participants'):[];$version=(int)($old['version']??0);$errors=[];
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){
    require_post_csrf();$data=industry_input($_POST);$version=(int)(filter_var($_POST['version']??null,FILTER_VALIDATE_INT)?:0);
    try{
        if(($_POST['form_complete']??'')!=='1'){throw new InvalidArgumentException('Formulir tidak lengkap. Muat ulang; periksa batas input server jika memilih banyak peserta.');}
        $selectedSpeakers=industry_ids($_POST['speakers']??[]);$selectedParticipants=industry_ids($_POST['participants']??[]);
        $saved=industry_save($data,$selectedSpeakers,$selectedParticipants,$id,$version,(int)$user['id']);panel_message('Kelas industri berhasil disimpan.','panel/kelas-industri/detail.php?id='.$saved);
    }catch(Throwable $exception){http_response_code(422);$errors[]=pkl_error($exception);}
}
$search=input_text($_GET,'q_siswa');
try{$studentResults=industry_participant_page($search,positive_id($_GET['page_siswa']??'1')??1);$chosenParticipants=industry_selected_participants($selectedParticipants);}
catch(InvalidArgumentException $exception){http_response_code(400);exit(e($exception->getMessage()));}
$participants=$studentResults['rows'];
$partners=panel_query("SELECT id,nama,aktif FROM mitra WHERE jenis='perusahaan' ORDER BY nama,id")->fetchAll();$speakers=panel_query('SELECT id,nama,instansi FROM speakers ORDER BY nama,id')->fetchAll();
panel_start($user,$id?'Edit kelas industri':'Tambah kelas industri','kelas-industri');
?>
<div class="industry-list-workspace industry-form-workspace">
<div class="page-actions industry-list-header"><div><h1><?= panel_icon('edit') ?> <?= $id?'Edit':'Tambah' ?> kelas industri</h1><p>Lengkapi empat bagian berikut, kemudian simpan kelas.</p></div><div class="industry-header-actions"><a class="button industry-description" href="<?= e(base_url('panel/kelas-industri/')) ?>"><?= panel_icon('back') ?> Daftar kelas</a></div></div>
<?php if($errors): ?><div class="notice" role="alert"><strong>Kelas belum disimpan.</strong><ul><?php foreach($errors as $error): ?><li><?= e($error) ?></li><?php endforeach; ?></ul></div><?php endif; ?>
<form id="industry-student-search" method="get"><?php if($id): ?><input type="hidden" name="id" value="<?= $id ?>"><?php endif; ?></form>
<form class="card industry-structured-form" method="post" data-industry-editor><?= csrf_field() ?><input type="hidden" name="version" value="<?= $version ?>">
<fieldset class="industry-form-section"><legend><span class="industry-step-number">1</span> Identitas kelas</legend><div class="industry-form-grid">
<label for="nama"><span><?= panel_icon('program') ?> Nama kelas *</span><input id="nama" name="nama" maxlength="190" value="<?= e($data['nama']) ?>" placeholder="Nama kelas industri" required></label>
<label for="status"><span><?= panel_icon('check-circle') ?> Status kelas</span><select id="status" name="status"><?php foreach(['aktif'=>'Aktif','arsip'=>'Arsip'] as $key=>$label): ?><option value="<?= $key ?>" <?= $data['status']===$key?'selected':'' ?>><?= $label ?></option><?php endforeach; ?></select><small>Aktif untuk kelas yang masih berjalan; Arsip untuk kelas yang sudah diarsipkan.</small></label></div></fieldset>
<fieldset class="industry-form-section"><legend><span class="industry-step-number">2</span> Mitra dan pemateri</legend>
<label for="mitra_id"><span><?= panel_icon('mitra') ?> Mitra industri *</span><select id="mitra_id" name="mitra_id" required><option value="">Pilih perusahaan mitra</option><?php foreach($partners as $partner): ?><option value="<?= $partner['id'] ?>" <?= (string)$partner['id']===$data['mitra_id']?'selected':'' ?>><?= e($partner['nama'].(!$partner['aktif']?' (nonaktif)':'')) ?></option><?php endforeach; ?></select></label>
<div class="industry-choice-heading"><h2 id="industry-speakers-label"><?= panel_icon('pemateri') ?> Pemateri kelas *</h2><span data-choice-count="speakers"><?= count($selectedSpeakers) ?> dipilih</span></div><p class="industry-field-help">Centang satu atau beberapa pemateri. Jika mitra/pemateri belum tersedia, minta pengelola modul terkait menambahkannya.</p>
<label class="industry-choice-search" for="industry-speaker-search"><span><?= panel_icon('search') ?> Cari pemateri dalam daftar</span><input id="industry-speaker-search" type="search" placeholder="Nama atau instansi" data-speaker-search></label>
<div class="industry-choice-list" data-speaker-list role="group" aria-labelledby="industry-speakers-label"><?php foreach($speakers as $speaker): ?><label class="industry-choice-row"><input type="checkbox" name="speakers[]" value="<?= (int)$speaker['id'] ?>" <?= in_array((int)$speaker['id'],$selectedSpeakers,true)?'checked':'' ?>><span><strong><?= e($speaker['nama']) ?></strong><small><?= e($speaker['instansi']?:'Instansi belum diisi') ?></small></span></label><?php endforeach; ?><?php if(!$speakers): ?><p class="industry-choice-empty">Belum ada pemateri. Tambahkan melalui menu Pemateri Kelas terlebih dahulu.</p><?php endif; ?></div><p class="industry-field-help" data-speaker-empty hidden>Tidak ada pemateri sesuai pencarian.</p></fieldset>
<fieldset class="industry-form-section"><legend><span class="industry-step-number">3</span> Sasaran dan peserta</legend>
<label for="kelas_sasaran"><span><?= panel_icon('program') ?> Kelas / kelompok sasaran</span><input id="kelas_sasaran" name="kelas_sasaran" maxlength="200" value="<?= e($data['kelas_sasaran']) ?>" placeholder="Nama kelas atau kelompok yang dituju"></label><p class="industry-field-help">Minimal isi sasaran di atas <strong>atau</strong> pilih siswa di bawah. Keduanya boleh diisi.</p>
<div class="industry-choice-heading"><h2 id="industry-students-label"><?= panel_icon('peserta') ?> Pilih siswa</h2><span data-choice-count="participants"><?= count($selectedParticipants) ?> dipilih</span></div>
<div class="industry-student-search"><label for="industry-student-query"><span><?= panel_icon('search') ?> Cari siswa berdasarkan nama atau kelas</span><input id="industry-student-query" form="industry-student-search" name="q_siswa" maxlength="100" value="<?= e($search) ?>" placeholder="Ketik nama atau kelas"></label><button type="submit" form="industry-student-search"><?= panel_icon('search') ?> Cari siswa</button></div>
<noscript><p class="notice">Pencarian memuat ulang halaman. Simpan perubahan terlebih dahulu sebelum mencari siswa lain.</p></noscript>
<p class="industry-field-help" data-student-search-status role="status">Cari nama atau kelas. Hasil ditampilkan 10 siswa per halaman; pilihan tetap tersedia saat berpindah halaman.</p>
<div data-student-results>
<div class="industry-result-caption"><strong>Hasil pencarian</strong><span><?= $studentResults['total']?($studentResults['page']-1)*10+1:0 ?>-<?= min($studentResults['page']*10,$studentResults['total']) ?> dari <?= number_format($studentResults['total'],0,',','.') ?> siswa</span></div>
<div class="industry-choice-list industry-student-list" data-student-list role="group" aria-labelledby="industry-students-label"><?php foreach($participants as $participant): $isChosen=in_array((int)$participant['id'],$selectedParticipants,true); ?><label class="industry-choice-row"><input type="checkbox" name="participants[]" value="<?= (int)$participant['id'] ?>" <?= $isChosen?'checked disabled':'' ?>><span><strong><?= e($participant['nama']) ?></strong><small><?= e($participant['kelas']) ?></small></span></label><?php endforeach; ?><?php if(!$participants): ?><p class="industry-choice-empty">Tidak ada siswa sesuai pencarian. Ubah nama atau kelas yang dicari.</p><?php endif; ?></div>
<nav class="industry-student-pages" aria-label="Halaman hasil pencarian siswa"><?php foreach(['Sebelumnya'=>$studentResults['page']-1,'Berikutnya'=>$studentResults['page']+1] as $label=>$target):if($target<1||$target>$studentResults['pages']){continue;} ?><a data-student-page href="<?= e(base_url('panel/kelas-industri/form.php?'.http_build_query(($id?['id'=>$id]:[])+['q_siswa'=>$search,'page_siswa'=>$target]).'#industry-students-label')) ?>"><?= $label ?></a><?php endforeach; ?><span>Halaman <?= $studentResults['page'] ?> dari <?= $studentResults['pages'] ?></span></nav>
</div>
<details class="industry-selected-panel"><summary><?= panel_icon('check-circle') ?> Siswa terpilih <span data-choice-count="participants"><?= count($selectedParticipants) ?> dipilih</span></summary><p class="industry-field-help">Periksa pilihan di sini. Lepas centang untuk mengeluarkan siswa dari kelas.</p><div class="industry-choice-list" data-selected-students role="group" aria-label="Siswa terpilih"><?php foreach($chosenParticipants as $participant): ?><label class="industry-choice-row"><input type="checkbox" name="participants[]" value="<?= (int)$participant['id'] ?>" checked><span><strong><?= e($participant['nama']) ?></strong><small><?= e($participant['kelas']) ?></small></span></label><?php endforeach; ?><?php if(!$chosenParticipants): ?><p class="industry-choice-empty" data-selected-empty>Belum ada siswa dipilih. Centang nama pada hasil pencarian.</p><?php endif; ?></div></details>
